// ============================================================================
// Colliding Balls - Common Parameters & Physics Helpers
// ============================================================================
const int N = 12;                   // Number of bouncing balls
const float mass = 1.0;             // Mass of each of the N bouncing balls
const float initialSpeed = 0.85;    // Initial speed of the N balls
const float ballRadius = 0.065;     // Radius of each of the N bouncing balls
const float userBallRadius = 0.10;  // Radius of the blue user mouse ball
const float userBallMass = 2.5;     // Mass of the blue user mouse ball acting on colliding balls
const float friction = 0.25;        // Velocity damping rate (higher = balls slow down faster; 0.0 = no friction)

// Alias kept for readability
const float userMass = userBallMass;

// Convert pixel coordinates to aspect-corrected arena coordinates:
// y in [-1, 1], x in [-aspect, aspect]
vec2 toArena(vec2 fragCoord, vec2 res) {
    return (2.0 * fragCoord - res) / max(res.y, 1.0);
}

// Get the user blue ball position in arena coordinates from iMouse
vec2 getMouseArenaPos(vec4 mouse, vec2 res) {
    if (mouse.x <= 0.0 && mouse.y <= 0.0) {
        return vec2(0.0, 0.0);
    }
    vec2 halfArena = vec2(res.x / max(res.y, 1.0), 1.0);
    vec2 limit = max(halfArena - vec2(userBallRadius), vec2(0.02));
    return clamp(toArena(mouse.xy, res), -limit, limit);
}

// 2D elastic collision velocity update for body 1 (mass m1, velocity v1)
// colliding with body 2 (mass m2, velocity v2) along unit normal (from body 2 to body 1).
vec2 collideElasticVel(vec2 v1, vec2 v2, float m1, float m2, vec2 normal, float restitution) {
    float relVel = dot(v1 - v2, normal);
    if (relVel >= 0.0) return v1;
    float invM1 = 1.0 / max(m1, 0.0001);
    float invM2 = 1.0 / max(m2, 0.0001);
    float j = -(1.0 + restitution) * relVel / (invM1 + invM2);
    return v1 + (j * invM1) * normal;
}

// Velocity rebound when a bouncing ball (mass ballMass) hits the mouse-driven
// user ball (mass uMass): impulse scales directly with uMass / ballMass.
vec2 collideUserBallVel(vec2 ballVel, vec2 userVel, float ballMass, float uMass, vec2 normal) {
    float relVel = dot(ballVel - userVel, normal);
    if (relVel >= 0.0) return ballVel;
    float massRatio = clamp(uMass / max(ballMass, 0.0001), 0.2, 5.0);
    float j = -(1.0 + massRatio) * relVel;
    return ballVel + j * normal;
}

// State layout in Buffer A:
// - Row 0, x in [0..N-1]: vec4(pos.x, pos.y, vel.x, vel.y) for ball x
// - Row 0, x == N:        vec4(userPos.x, userPos.y, userVel.x, userVel.y)
// - Row 1, x in [0..N-1]: vec4(lastBallHitTime, lastBorderHitTime, hitImpact, hitPan)
// - Row 1, x == N:        vec4(initializedMarker, latestBorderHitTime, mouseActive, 0.0)

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    ivec2 ipx = ivec2(fragCoord - 0.5);
    if (ipx.x < 0 || ipx.y < 0 || ipx.x > N || ipx.y > 1) {
        fragColor = vec4(0.0);
        return;
    }

    vec2 halfArena = vec2(iResolution.x / max(iResolution.y, 1.0), 1.0);
    vec2 ballLimit = max(halfArena - vec2(ballRadius), vec2(0.05));
    vec4 prevMeta = texelFetch(iChannel0, ivec2(N, 1), 0);
    float initMarker = prevMeta.x;

    // Initialize state on Frame 0 or after buffer reset/resize
    if (iFrame == 0 || initMarker < 0.5) {
        if (ipx.y == 1) {
            if (ipx.x == N) {
                fragColor = vec4(1.0, -10.0, 0.0, 0.0);
            } else {
                fragColor = vec4(-10.0, -10.0, 0.0, 0.0);
            }
            return;
        }

        if (ipx.x == N) {
            vec2 uPos = getMouseArenaPos(iMouse, iResolution.xy);
            fragColor = vec4(uPos, 0.0, 0.0);
            return;
        }

        float fi = float(ipx.x);
        float fn = float(max(N, 1));
        float goldenAngle = 2.39996323;
        float a = fi * goldenAngle + 0.4;
        float rFrac = 0.32 + 0.58 * sqrt((fi + 0.5) / fn);
        vec2 pos = vec2(cos(a) * halfArena.x * 0.85, sin(a) * 0.85) * rFrac;
        pos = clamp(pos, -ballLimit * 0.92, ballLimit * 0.92);

        vec2 uStart = getMouseArenaPos(iMouse, iResolution.xy);
        vec2 dU = pos - uStart;
        float minStartDist = userBallRadius + ballRadius + 0.06;
        float lenU = length(dU);
        if (lenU < minStartDist) {
            vec2 dir = (lenU > 1e-4) ? (dU / lenU) : vec2(cos(a), sin(a));
            pos = clamp(uStart + dir * minStartDist, -ballLimit * 0.92, ballLimit * 0.92);
        }

        float va = fi * goldenAngle + 1.25;
        vec2 vel = vec2(cos(va), sin(va)) * initialSpeed;
        fragColor = vec4(pos, vel);
        return;
    }

    float dt = clamp(iTimeDelta, 0.001, 0.033);
    vec4 prevUser = texelFetch(iChannel0, ivec2(N, 0), 0);
    vec2 userPos = getMouseArenaPos(iMouse, iResolution.xy);
    vec2 userDelta = userPos - prevUser.xy;
    bool hadActiveMouse = (prevMeta.z > 0.5);
    vec2 rawUserVel = (hadActiveMouse && length(userDelta) < 0.65)
        ? clamp(userDelta / dt, vec2(-4.5), vec2(4.5))
        : vec2(0.0);
    vec2 userVel = mix(rawUserVel, prevUser.zw, 0.45);
    float mouseActive = (iMouse.x > 0.0 || iMouse.y > 0.0) ? 1.0 : 0.0;

    if (ipx.y == 0 && ipx.x == N) {
        fragColor = vec4(userPos, userVel);
        return;
    }

    if (ipx.y == 1 && ipx.x == N) {
        float latestBorderTime = prevMeta.y;
        for (int j = 0; j < N; j++) {
            float bt = texelFetch(iChannel0, ivec2(j, 1), 0).y;
            latestBorderTime = max(latestBorderTime, bt);
        }
        fragColor = vec4(1.0, latestBorderTime, mouseActive, 0.0);
        return;
    }

    int idx = ipx.x;
    vec4 state = texelFetch(iChannel0, ivec2(idx, 0), 0);
    vec4 events = texelFetch(iChannel0, ivec2(idx, 1), 0);

    vec2 pos = state.xy;
    vec2 vel = state.zw;
    pos += vel * dt;

    float lastBallHit = events.x;
    float lastBorderHit = events.y;
    float hitImpact = events.z;
    float hitPan = events.w;

    bool triggeredBallHit = false;
    bool triggeredBorderHit = false;
    float maxBallImpact = 0.0;
    float maxBorderImpact = 0.0;
    float ballHitPosX = pos.x;
    float borderHitPosX = pos.x;

    // 1. Ball vs. blue mouse-controlled user ball
    {
        float minDist = ballRadius + userBallRadius;
        vec2 diff = pos - userPos;
        float dist = length(diff);
        if (dist < minDist) {
            vec2 n = (dist > 1e-5)
                ? (diff / dist)
                : normalize(vec2(cos(float(idx) + 0.5), sin(float(idx) + 0.5)));
            float relVel = dot(vel - userVel, n);
            pos = userPos + n * (minDist + 0.0005);
            if (relVel < 0.0) {
                vel = collideUserBallVel(vel, userVel, mass, userBallMass, n);
                if (relVel < -0.04 && (iTime - lastBallHit) > 0.045) {
                    triggeredBallHit = true;
                    maxBallImpact = max(maxBallImpact, clamp(-relVel / max(initialSpeed, 0.1), 0.1, 2.0));
                    ballHitPosX = 0.5 * (pos.x + userPos.x);
                }
            }
        }
    }

    // 2. Ball vs. other N - 1 balls (equal mass-based 2D elastic rebound)
    float minBallDist = 2.0 * ballRadius;
    for (int j = 0; j < N; j++) {
        if (j == idx) continue;
        vec4 other = texelFetch(iChannel0, ivec2(j, 0), 0);
        vec2 otherPos = other.xy + other.zw * dt;
        vec2 otherVel = other.zw;

        vec2 diff = pos - otherPos;
        float dist = length(diff);
        if (dist < minBallDist) {
            vec2 n = (dist > 1e-5)
                ? (diff / dist)
                : normalize(vec2(cos(float(idx * 7 + j)), sin(float(idx * 7 + j))));
            float overlap = minBallDist - dist;
            pos += n * (0.5 * overlap + 0.00025);

            float relVel = dot(vel - otherVel, n);
            if (relVel < 0.0) {
                vel = collideElasticVel(vel, otherVel, mass, mass, n, 1.0);
                if (relVel < -0.04 && (iTime - lastBallHit) > 0.045) {
                    triggeredBallHit = true;
                    maxBallImpact = max(maxBallImpact, clamp(-relVel / max(initialSpeed, 0.1), 0.1, 2.0));
                    ballHitPosX = 0.5 * (pos.x + otherPos.x);
                }
            }
        }
    }

    // 3. Ball vs. arena borders
    if (pos.x < -ballLimit.x) {
        pos.x = -ballLimit.x;
        if (vel.x < 0.0) {
            float impactSpeed = abs(vel.x);
            vel.x = -vel.x;
            if (impactSpeed > 0.04 && (iTime - lastBorderHit) > 0.045) {
                triggeredBorderHit = true;
                maxBorderImpact = max(maxBorderImpact, clamp(impactSpeed / max(initialSpeed, 0.1), 0.1, 2.0));
                borderHitPosX = pos.x;
            }
        }
    } else if (pos.x > ballLimit.x) {
        pos.x = ballLimit.x;
        if (vel.x > 0.0) {
            float impactSpeed = abs(vel.x);
            vel.x = -vel.x;
            if (impactSpeed > 0.04 && (iTime - lastBorderHit) > 0.045) {
                triggeredBorderHit = true;
                maxBorderImpact = max(maxBorderImpact, clamp(impactSpeed / max(initialSpeed, 0.1), 0.1, 2.0));
                borderHitPosX = pos.x;
            }
        }
    }

    if (pos.y < -ballLimit.y) {
        pos.y = -ballLimit.y;
        if (vel.y < 0.0) {
            float impactSpeed = abs(vel.y);
            vel.y = -vel.y;
            if (impactSpeed > 0.04 && (iTime - lastBorderHit) > 0.045) {
                triggeredBorderHit = true;
                maxBorderImpact = max(maxBorderImpact, clamp(impactSpeed / max(initialSpeed, 0.1), 0.1, 2.0));
                borderHitPosX = pos.x;
            }
        }
    } else if (pos.y > ballLimit.y) {
        pos.y = ballLimit.y;
        if (vel.y > 0.0) {
            float impactSpeed = abs(vel.y);
            vel.y = -vel.y;
            if (impactSpeed > 0.04 && (iTime - lastBorderHit) > 0.045) {
                triggeredBorderHit = true;
                maxBorderImpact = max(maxBorderImpact, clamp(impactSpeed / max(initialSpeed, 0.1), 0.1, 2.0));
                borderHitPosX = pos.x;
            }
        }
    }

    // Apply frame-rate-independent friction damping and clamp velocity
    vel *= exp(-max(friction, 0.0) * dt);
    float speed = length(vel);
    float maxSpeed = 3.5 * max(initialSpeed, 0.1);
    if (speed < 0.003) {
        vel = vec2(0.0);
    } else if (speed > maxSpeed) {
        vel *= maxSpeed / speed;
    }

    if (triggeredBallHit) {
        lastBallHit = iTime;
        hitImpact = maxBallImpact;
        hitPan = clamp(ballHitPosX / max(halfArena.x, 1.0), -1.0, 1.0);
    }
    if (triggeredBorderHit) {
        lastBorderHit = iTime;
        hitImpact = max(maxBorderImpact, hitImpact * 0.5);
        hitPan = clamp(borderHitPosX / max(halfArena.x, 1.0), -1.0, 1.0);
    }

    if (ipx.y == 0) {
        fragColor = vec4(pos, vel);
    } else {
        fragColor = vec4(lastBallHit, lastBorderHit, hitImpact, hitPan);
    }
}

vec3 shadeSphere(vec2 d, float radius, float px, vec3 baseColor, vec3 rimColor, float hitGlow, out float alpha) {
    float dist = length(d);
    alpha = 1.0 - smoothstep(radius - px, radius + px, dist);
    if (alpha <= 0.001) return vec3(0.0);

    vec2 nxy = d / max(radius, 1e-4);
    float nz = sqrt(max(0.0, 1.0 - dot(nxy, nxy)));
    vec3 n = vec3(nxy, nz);

    vec3 lightDir = normalize(vec3(-0.45, 0.65, 0.75));
    vec3 halfVec = normalize(lightDir + vec3(0.0, 0.0, 1.0));
    float diff = max(dot(n, lightDir), 0.0);
    float spec = pow(max(dot(n, halfVec), 0.0), 36.0);
    float fresnel = pow(1.0 - nz, 2.5);

    vec3 lit = baseColor * (0.30 + 0.75 * diff)
             + vec3(1.0) * (0.45 * spec)
             + rimColor * (0.35 * fresnel)
             + vec3(1.0, 0.95, 0.85) * (0.45 * hitGlow);
    return lit;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = toArena(fragCoord, iResolution.xy);
    float px = 2.0 / max(iResolution.y, 1.0);
    vec2 halfArena = vec2(iResolution.x / max(iResolution.y, 1.0), 1.0);

    // Studio background with subtle grid
    vec3 col = mix(vec3(0.06, 0.08, 0.12), vec3(0.025, 0.035, 0.055), 0.45 * length(uv));
    vec2 grid = abs(fract(uv * 4.0 - 0.5) - 0.5) / (4.0 * px);
    float gridLine = 1.0 - min(min(grid.x, grid.y), 1.0);
    col += vec3(0.03, 0.045, 0.07) * gridLine * 0.5;

    // Arena border line with subtle flash on border impacts
    vec4 meta = texelFetch(iChannel0, ivec2(N, 1), 0);
    float borderFlash = (meta.y >= 0.0) ? exp(-9.0 * max(0.0, iTime - meta.y)) : 0.0;
    float edgeDistX = abs(abs(uv.x) - halfArena.x);
    float edgeDistY = abs(abs(uv.y) - 1.0);
    float borderDist = min(edgeDistX, edgeDistY);
    float borderGlow = exp(-260.0 * borderDist * borderDist) + 0.55 * (1.0 - smoothstep(0.0, 3.0 * px, borderDist));
    col += mix(vec3(0.18, 0.34, 0.55), vec3(0.95, 0.72, 0.35), borderFlash) * borderGlow * (0.45 + 0.55 * borderFlash);

    // Blue user ball (moved with the mouse)
    vec4 userState = texelFetch(iChannel0, ivec2(N, 0), 0);
    vec2 userPos = userState.xy;
    vec2 du = uv - userPos;
    float duLen = length(du);
    float userShadow = 1.0 - smoothstep(userBallRadius * 0.4, userBallRadius * 1.6, length(du + vec2(-0.015, 0.02)));
    col *= mix(1.0, 0.55, 0.5 * userShadow);
    // Soft outer cyan halo
    col += vec3(0.12, 0.55, 1.0) * exp(-25.0 * max(0.0, duLen - userBallRadius)) * 0.30;
    float userAlpha;
    vec3 userCol = shadeSphere(
        du,
        userBallRadius,
        px,
        vec3(0.12, 0.48, 0.98),
        vec3(0.45, 0.88, 1.0),
        0.0,
        userAlpha
    );
    col = mix(col, userCol, userAlpha);

    // Render N bouncing balls
    for (int i = 0; i < N; i++) {
        vec4 st = texelFetch(iChannel0, ivec2(i, 0), 0);
        vec4 ev = texelFetch(iChannel0, ivec2(i, 1), 0);
        vec2 bPos = st.xy;

        float ballGlow = (ev.x >= 0.0) ? exp(-9.0 * max(0.0, iTime - ev.x)) : 0.0;
        float wallGlow = (ev.y >= 0.0) ? exp(-11.0 * max(0.0, iTime - ev.y)) : 0.0;
        float hitGlow = max(ballGlow, wallGlow);

        vec2 d = uv - bPos;
        float dLen = length(d);

        // Shadow
        float sh = 1.0 - smoothstep(ballRadius * 0.4, ballRadius * 1.5, length(d + vec2(-0.012, 0.018)));
        col *= mix(1.0, 0.58, 0.45 * sh);

        // Palette tuned to keep the user ball distinctively blue
        float hue = 0.06 + 0.62 * float(i) / float(max(N, 1));
        vec3 bBase = 0.56 + 0.38 * cos(6.2831853 * hue + vec3(0.0, 2.094, 4.188));

        // Collision pulse ring
        if (hitGlow > 0.02) {
            float ringR = ballRadius + (1.0 - hitGlow) * ballRadius * 1.1;
            float ringD = abs(dLen - ringR);
            col += mix(bBase, vec3(1.0, 0.95, 0.8), 0.5) * exp(-1800.0 * ringD * ringD) * hitGlow;
        }

        float bAlpha;
        vec3 bCol = shadeSphere(d, ballRadius, px, bBase, vec3(1.0, 0.9, 0.8), hitGlow, bAlpha);
        col = mix(col, bCol, bAlpha);
    }

    fragColor = vec4(col, 1.0);
}

vec2 mainSound(int samp, float time) {
    vec2 sig = vec2(0.0);

    for (int i = 0; i < N; i++) {
        vec4 ev = texelFetch(iChannel0, ivec2(i, 1), 0);
        float impact = clamp(ev.z, 0.15, 2.0);
        float pan = clamp(ev.w, -1.0, 1.0);

        vec2 panGain = vec2(
            sqrt(clamp(0.5 * (1.0 - pan), 0.0, 1.0)),
            sqrt(clamp(0.5 * (1.0 + pan), 0.0, 1.0))
        );

        // Ball-to-ball or ball-to-user collision sound
        if (ev.x >= 0.0) {
            float dtBall = time - ev.x;
            if (dtBall >= 0.0 && dtBall < 0.22) {
                float baseFreq = 340.0 + mod(float(i) * 59.0, 420.0) + impact * 85.0;
                float env = exp(-22.0 * dtBall)
                          * smoothstep(0.0, 0.002, dtBall)
                          * (1.0 - smoothstep(0.18, 0.22, dtBall));
                float tone = 0.72 * sin(6.2831853 * baseFreq * dtBall)
                           + 0.28 * sin(6.2831853 * baseFreq * 2.41 * dtBall) * exp(-18.0 * dtBall);
                float amp = (0.13 + 0.10 * impact) * env;
                sig += panGain * (tone * amp);
            }
        }

        // Border collision sound (deeper woody wall knock)
        if (ev.y >= 0.0) {
            float dtWall = time - ev.y;
            if (dtWall >= 0.0 && dtWall < 0.16) {
                float wallFreq = 135.0 + mod(float(i) * 19.0, 95.0);
                float phase = 6.2831853 * (wallFreq * dtWall + 0.65 * (1.0 - exp(-40.0 * dtWall)));
                float env = exp(-28.0 * dtWall)
                          * smoothstep(0.0, 0.0015, dtWall)
                          * (1.0 - smoothstep(0.13, 0.16, dtWall));
                float tone = 0.80 * sin(phase) + 0.20 * sin(2.0 * phase) * exp(-25.0 * dtWall);
                float amp = (0.14 + 0.09 * impact) * env;
                sig += panGain * (tone * amp);
            }
        }
    }

    return sig / sqrt(1.0 + sig * sig);
}
